#pragma once

#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <string>
#include <optional>
#include <vector>

namespace ptv {

// Local component holding current locomotion prefs for global consumption.
struct CLocomotionSettings {
    enum class Mode : std::uint8_t { Teleport = 0, SlideHead = 1, SlideController = 2 };

    Mode   mode{Mode::SlideHead};
    float  snap_degrees{45.0f};
    float  snap_cooldown_s{0.30f};

    bool   vignette_enabled{true};
    float  vignette_intensity{0.5f}; // 0..1; HUD may adjust; engine does not render here.

    bool   smooth_turn_enabled{false};
    float  smooth_turn_rate_dps{120.0f}; // When smooth turn is chosen.

    bool   dirty{true}; // Set true when something changed and needs applying/persisting.
};

// Lightweight saved-settings blob (shim). Real system should replace this.
struct CSavedSettings {
    // Keys: locomotion.mode, locomotion.snap_deg, locomotion.snap_cd,
    //       locomotion.smooth_turn_rate, locomotion.vignette
    nlohmann::json kv{nlohmann::json::object()};
};

// Helpers
inline bool tag_list_has(const std::vector<std::string>& tags, const std::string& t) {
    for (const auto& s : tags) if (s == t) return true; return false;
}

inline void ensure_service_tag(World& w, std::uint32_t e) {
    if (w.has<CTag>(e)) {
        auto& tag = w.get<CTag>(e);
        if (!tag_list_has(tag.tags, "locomotion_settings")) tag.tags.push_back("locomotion_settings");
    } else {
        CTag t; t.tags.push_back("locomotion_settings");
        w.emplace_or_replace<CTag>(e, std::move(t));
    }
}

inline std::optional<nlohmann::json> find_own_binding_params(World& w, std::uint32_t e, const std::string& my_id) {
    if (!w.has<CMechanicBinding>(e)) return std::nullopt;
    auto& mb = w.get<CMechanicBinding>(e);
    for (const auto& ent : mb.entries) {
        if (ent.id == my_id || ent.builtin_id == my_id) {
            auto j = nlohmann::json::parse(ent.params_json, nullptr, false);
            if (j.is_discarded()) return nlohmann::json::object();
            if (!j.is_object()) return nlohmann::json::object();
            return j;
        }
    }
    return std::nullopt;
}

// Apply enable flag onto a binding entry's params_json (non-destructive merge).
inline void set_binding_enabled_flag(nlohmann::json& params, bool enabled) {
    // Write/overwrite a conventional runtime key.
    params["enabled"] = enabled;
}

inline void write_turn_params(nlohmann::json& params, float degrees, float cooldown_s) {
    params["degrees"] = degrees;
    params["cooldown_s"] = cooldown_s;
}

// Find and mutate well-known builtin locomotion binding params in-place.
inline void apply_enable_matrix_to_bindings(World& w, bool en_tele, bool en_head, bool en_ctrl, bool en_snap,
                                            float snap_deg, float snap_cd) {
    auto& reg = w.registry();
    auto view = reg.view<CMechanicBinding>();
    for (auto ent : view) {
        auto& mb = view.get<CMechanicBinding>(ent);
        for (auto& entry : mb.entries) {
            const std::string& id = !entry.id.empty() ? entry.id : entry.builtin_id;
            if (id.empty()) continue;
            if (id == "builtin.locomotion.teleport" || id == "locomotion_teleport") {
                auto j = nlohmann::json::parse(entry.params_json, nullptr, false);
                if (!j.is_object()) j = nlohmann::json::object();
                set_binding_enabled_flag(j, en_tele);
                entry.params_json = j.dump();
            } else if (id == "builtin.locomotion.slide.head_relative" || id == "locomotion_slide_head") {
                auto j = nlohmann::json::parse(entry.params_json, nullptr, false);
                if (!j.is_object()) j = nlohmann::json::object();
                set_binding_enabled_flag(j, en_head);
                entry.params_json = j.dump();
            } else if (id == "builtin.locomotion.slide.controller_relative" || id == "locomotion_slide_controller") {
                auto j = nlohmann::json::parse(entry.params_json, nullptr, false);
                if (!j.is_object()) j = nlohmann::json::object();
                set_binding_enabled_flag(j, en_ctrl);
                entry.params_json = j.dump();
            } else if (id == "builtin.locomotion.snap_turn" || id == "locomotion_snap_turn") {
                auto j = nlohmann::json::parse(entry.params_json, nullptr, false);
                if (!j.is_object()) j = nlohmann::json::object();
                set_binding_enabled_flag(j, en_snap);
                write_turn_params(j, snap_deg, snap_cd);
                entry.params_json = j.dump();
            }
        }
    }
}

// Persistence shim.
inline void persist_settings_if_present(World& w, std::uint32_t e, const CLocomotionSettings& s) {
    if (!w.has<CSavedSettings>(e)) return; // If save system binds later, this will start working automatically.
    auto& save = w.get<CSavedSettings>(e);
    save.kv["locomotion.mode"] = static_cast<int>(s.mode);
    save.kv["locomotion.snap_deg"] = s.snap_degrees;
    save.kv["locomotion.snap_cd"] = s.snap_cooldown_s;
    save.kv["locomotion.smooth_turn_rate"] = s.smooth_turn_rate_dps;
    save.kv["locomotion.vignette"] = s.vignette_enabled;
}

inline void load_settings_if_present(World& w, std::uint32_t e, CLocomotionSettings& s) {
    if (!w.has<CSavedSettings>(e)) return;
    auto& save = w.get<CSavedSettings>(e);
    if (save.kv.contains("locomotion.mode")) s.mode = static_cast<CLocomotionSettings::Mode>(save.kv["locomotion.mode"].get<int>());
    if (save.kv.contains("locomotion.snap_deg")) s.snap_degrees = save.kv["locomotion.snap_deg"].get<float>();
    if (save.kv.contains("locomotion.snap_cd")) s.snap_cooldown_s = save.kv["locomotion.snap_cd"].get<float>();
    if (save.kv.contains("locomotion.smooth_turn_rate")) s.smooth_turn_rate_dps = save.kv["locomotion.smooth_turn_rate"].get<float>();
    if (save.kv.contains("locomotion.vignette")) s.vignette_enabled = save.kv["locomotion.vignette"].get<bool>();
}

// Compute and push enable matrix based on settings.
inline void apply_settings_globally(World& w, const CLocomotionSettings& s) {
    const bool en_tele = (s.mode == CLocomotionSettings::Mode::Teleport);
    const bool en_head = (s.mode == CLocomotionSettings::Mode::SlideHead);
    const bool en_ctrl = (s.mode == CLocomotionSettings::Mode::SlideController);
    const bool en_snap = !s.smooth_turn_enabled; // Snap on unless smooth selected.
    apply_enable_matrix_to_bindings(w, en_tele, en_head, en_ctrl, en_snap, s.snap_degrees, s.snap_cooldown_s);
}

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <string>

#include "locomotion_settings_menu_shared.h"

namespace ptv {

class LocomotionSettingsMenu : public IMechanic {
public:
    void on_attach(World& w, std::uint32_t e, const nlohmann::json& params) override {
        // Ensure service tag so other systems can find this owner as the settings source.
        ensure_service_tag(w, e);

        // Seed defaults from binding params first (if present), fall back to provided params, then hard defaults.
        CLocomotionSettings s{};
        s.mode = CLocomotionSettings::Mode::SlideHead;
        s.snap_degrees = 45.0f;
        s.snap_cooldown_s = 0.30f;
        s.vignette_enabled = true;
        s.vignette_intensity = 0.5f;
        s.smooth_turn_enabled = false;
        s.smooth_turn_rate_dps = 120.0f;
        s.dirty = true;

        // Read this mechanic's binding JSON (if any) for defaults.
        if (auto jb = find_own_binding_params(w, e, id()); jb.has_value()) {
            const auto& j = *jb;
            const std::string def_mode = j.value("default_mode", params.value("default_mode", std::string("slide_head")));
            if (def_mode == "teleport") s.mode = CLocomotionSettings::Mode::Teleport;
            else if (def_mode == "slide_controller") s.mode = CLocomotionSettings::Mode::SlideController;
            else s.mode = CLocomotionSettings::Mode::SlideHead;

            s.snap_degrees = j.value("default_snap_deg", params.value("default_snap_deg", 45.0f));
            s.snap_cooldown_s = j.value("default_snap_cooldown_s", params.value("default_snap_cooldown_s", 0.30f));
            s.vignette_enabled = j.value("default_vignette", params.value("default_vignette", true));
            // Smooth turn is chosen via HUD; start disabled unless a binding asks otherwise.
            s.smooth_turn_enabled = j.value("default_smooth_turn", params.value("default_smooth_turn", false));
            s.smooth_turn_rate_dps = j.value("default_smooth_turn_rate_dps", params.value("default_smooth_turn_rate_dps", 120.0f));
        } else {
            const std::string def_mode = params.value("default_mode", std::string("slide_head"));
            if (def_mode == "teleport") s.mode = CLocomotionSettings::Mode::Teleport;
            else if (def_mode == "slide_controller") s.mode = CLocomotionSettings::Mode::SlideController;
            else s.mode = CLocomotionSettings::Mode::SlideHead;

            s.snap_degrees = params.value("default_snap_deg", 45.0f);
            s.snap_cooldown_s = params.value("default_snap_cooldown_s", 0.30f);
            s.vignette_enabled = params.value("default_vignette", true);
            s.smooth_turn_enabled = params.value("default_smooth_turn", false);
            s.smooth_turn_rate_dps = params.value("default_smooth_turn_rate_dps", 120.0f);
        }

        // Load overrides from persistence if present.
        if (!w.has<CSavedSettings>(e)) {
            // Create an empty blob to allow immediate write-through persistence.
            w.emplace_or_replace<CSavedSettings>(e, CSavedSettings{});
        }
        load_settings_if_present(w, e, s);

        // Publish the singleton component.
        w.emplace_or_replace<CLocomotionSettings>(e, s);

        // Apply immediately to world so locomotion starts in the chosen mode.
        apply_settings_globally(w, s);
        persist_settings_if_present(w, e, s);
    }

    void on_update(World& w, std::uint32_t e, float /*dt*/) override {
        if (!w.has<CLocomotionSettings>(e)) return;
        auto& s = w.get<CLocomotionSettings>(e);
        if (!s.dirty) return;
        s.dirty = false;
        // Enforce exclusivity and snap/smooth policy.
        apply_settings_globally(w, s);
        persist_settings_if_present(w, e, s);
        // Ensure the service tag remains present (other mechanics may replace CTag).
        ensure_service_tag(w, e);
    }

    void on_detach(World& w, std::uint32_t e) override {
        // Keep saved settings; drop live singleton.
        if (w.has<CLocomotionSettings>(e)) w.remove<CLocomotionSettings>(e);
        // Leave CTag and CSavedSettings in place so re-binding restores last values.
    }

    std::string id() const override { return "generated.locomotion_settings_menu"; }
};

PTV_REGISTER_MECHANIC("generated.locomotion_settings_menu", LocomotionSettingsMenu)

} // namespace ptv

#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <nlohmann/json.hpp>
#include <string>

#include "locomotion_settings_menu_shared.h"

namespace ptv {

// Convenience API other systems (e.g., HUD) can call by editing the singleton then setting dirty=true.
// To help tests, we expose small helpers via weakly-linked C-style names (not required by engine).

// Change locomotion mode.
static void set_mode(CL ocomotionSettings& s, const std::string& mode) {
    if (mode == "teleport") s.mode = CLocomotionSettings::Mode::Teleport;
    else if (mode == "slide_controller") s.mode = CLocomotionSettings::Mode::SlideController;
    else s.mode = CLocomotionSettings::Mode::SlideHead;
}

// Internal utility to sanitize settings before apply.
static void sanitize(CL ocomotionSettings& s) {
    if (s.snap_degrees < 5.0f) s.snap_degrees = 5.0f;
    if (s.snap_degrees > 90.0f) s.snap_degrees = 90.0f;
    if (s.snap_cooldown_s < 0.0f) s.snap_cooldown_s = 0.0f;
    if (s.vignette_intensity < 0.0f) s.vignette_intensity = 0.0f;
    if (s.vignette_intensity > 1.0f) s.vignette_intensity = 1.0f;
    if (s.smooth_turn_rate_dps < 30.0f) s.smooth_turn_rate_dps = 30.0f;
    if (s.smooth_turn_rate_dps > 360.0f) s.smooth_turn_rate_dps = 360.0f;
}

// Public helper callable from tests via symbol lookup if needed.
extern "C" void ptv_locomotion_apply_settings(World* world, std::uint32_t owner_entity,
                                              const char* json_settings_blob) {
    if (!world || !world->valid(owner_entity)) return;
    auto& w = *world;
    if (!w.has<CLocomotionSettings>(owner_entity)) return;
    auto& s = w.get<CLocomotionSettings>(owner_entity);

    auto j = nlohmann::json::parse(json_settings_blob ? json_settings_blob : "{}", nullptr, false);
    if (!j.is_object()) j = nlohmann::json::object();

    if (j.contains("mode")) set_mode(s, j["mode"].get<std::string>());
    if (j.contains("snap_degrees")) s.snap_degrees = j["snap_degrees"].get<float>();
    if (j.contains("snap_cooldown_s")) s.snap_cooldown_s = j["snap_cooldown_s"].get<float>();
    if (j.contains("vignette_enabled")) s.vignette_enabled = j["vignette_enabled"].get<bool>();
    if (j.contains("vignette_intensity")) s.vignette_intensity = j["vignette_intensity"].get<float>();

    if (j.contains("turn")) {
        const auto turn = j["turn"].get<std::string>();
        if (turn == "smooth") s.smooth_turn_enabled = true; else if (turn == "snap") s.smooth_turn_enabled = false;
    }
    if (j.contains("smooth_turn_rate_dps")) s.smooth_turn_rate_dps = j["smooth_turn_rate_dps"].get<float>();

    sanitize(s);
    s.dirty = true; // Let the registered mechanic apply/persist next frame.
}

// Getter for HUD/tests.
extern "C" int ptv_locomotion_get_settings(World* world, std::uint32_t owner_entity, char* out_json, int out_cap) {
    if (!world || !world->valid(owner_entity) || out_cap <= 2) return 0;
    auto& w = *world;
    if (!w.has<CLocomotionSettings>(owner_entity)) return 0;
    const auto& s = w.get<CLocomotionSettings>(owner_entity);

    nlohmann::json j = nlohmann::json::object();
    std::string mode = (s.mode == CLocomotionSettings::Mode::Teleport) ? "teleport" : (s.mode == CLocomotionSettings::Mode::SlideController ? "slide_controller" : "slide_head");
    j["mode"] = mode;
    j["snap_degrees"] = s.snap_degrees;
    j["snap_cooldown_s"] = s.snap_cooldown_s;
    j["vignette_enabled"] = s.vignette_enabled;
    j["vignette_intensity"] = s.vignette_intensity;
    j["smooth_turn_enabled"] = s.smooth_turn_enabled;
    j["smooth_turn_rate_dps"] = s.smooth_turn_rate_dps;

    const std::string dump = j.dump();
    const int n = static_cast<int>(dump.size());
    const int to_copy = (n < out_cap - 1) ? n : (out_cap - 1);
    std::memcpy(out_json, dump.data(), static_cast<size_t>(to_copy));
    out_json[to_copy] = '\0';
    return to_copy;
}

} // namespace ptv

#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <nlohmann/json.hpp>

#include "locomotion_settings_menu_shared.h"

namespace ptv {

// Optional explicit persist/load helpers for future save_load_system to call.
extern "C" void ptv_locomotion_force_persist(World* world, std::uint32_t owner_entity) {
    if (!world || !world->valid(owner_entity)) return;
    auto& w = *world;
    if (!w.has<CLocomotionSettings>(owner_entity)) return;
    const auto& s = w.get<CLocomotionSettings>(owner_entity);
    persist_settings_if_present(w, owner_entity, s);
}

extern "C" void ptv_locomotion_try_load(World* world, std::uint32_t owner_entity) {
    if (!world || !world->valid(owner_entity)) return;
    auto& w = *world;
    if (!w.has<CLocomotionSettings>(owner_entity)) return;
    auto& s = w.get<CLocomotionSettings>(owner_entity);
    load_settings_if_present(w, owner_entity, s);
    s.dirty = true; // Re-apply after load.
}

} // namespace ptv
